pub trait UserDao: Send + Sync {
    fn find(&self, id: i64) -> Result<Option<User>, DaoError>;
}

pub fn user_dao(store: Store, pool: Pool) -> Box<dyn UserDao> {
    match store {
        Store::Postgres => Box::new(PgUserDao::new(pool)),   // SQL lives in the impl
        Store::Sqlite => Box::new(SqliteUserDao::new(pool)),
    }
}

